import { useMemo, useState } from "react";
import {
  Button,
  FieldFrame,
  Modal,
  PageHeader,
  Select,
  StatusPill,
  TextField,
} from "@autograph/components";
import { RecordDetailPanel } from "@autograph/compositions";
import { Refresh } from "@autograph/icons";
import "./stock-exceptions.css";

type Severity = "Critical" | "Low";
type ExceptionItem = {
  id: string;
  sku: string;
  product: string;
  location: string;
  severity: Severity;
  onHand: number;
  reorderPoint: number;
  dailySales: number;
  supplier: string;
  leadTime: string;
  minimumOrder: number;
  unitCost: string;
  openPo: string;
  suggested: number;
};

const ITEMS: ExceptionItem[] = [
  { id: "sku-1048", sku: "1048", product: "Organic Oat Milk 1L", location: "Downtown", severity: "Critical", onHand: 3, reorderPoint: 18, dailySales: 7.4, supplier: "North Valley Foods", leadTime: "3 days", minimumOrder: 24, unitCost: "$2.10", openPo: "None", suggested: 48 },
  { id: "sku-2271", sku: "2271", product: "Sparkling Water · Lime 8pk", location: "Downtown", severity: "Low", onHand: 11, reorderPoint: 24, dailySales: 5.1, supplier: "Clear Springs Co.", leadTime: "5 days", minimumOrder: 12, unitCost: "$3.85", openPo: "PO-8831 · 12 due Fri", suggested: 24 },
  { id: "sku-3180", sku: "3180", product: "Whole Bean Coffee 340g", location: "Airport", severity: "Critical", onHand: 2, reorderPoint: 14, dailySales: 4.8, supplier: "Harbor Roasters", leadTime: "4 days", minimumOrder: 18, unitCost: "$7.20", openPo: "None", suggested: 36 },
  { id: "sku-4426", sku: "4426", product: "Almond Butter 250g", location: "Northside", severity: "Low", onHand: 8, reorderPoint: 15, dailySales: 2.2, supplier: "Field & Grove", leadTime: "6 days", minimumOrder: 12, unitCost: "$4.60", openPo: "PO-8824 · 12 due Mon", suggested: 12 },
];

export default function StockExceptionsScreen() {
  const [location, setLocation] = useState("all");
  const [severity, setSeverity] = useState("all");
  const [selectedId, setSelectedId] = useState(ITEMS[0].id);
  const [modalOpen, setModalOpen] = useState(false);
  const [quantity, setQuantity] = useState(String(ITEMS[0].suggested));
  const [error, setError] = useState("");
  const [mockOrders, setMockOrders] = useState<Record<string, number>>({});

  const filtered = useMemo(() => ITEMS.filter((item) => (location === "all" || item.location === location) && (severity === "all" || item.severity === severity)), [location, severity]);
  const selected = ITEMS.find((item) => item.id === selectedId) ?? filtered[0] ?? null;

  function changeFilters(nextLocation: string, nextSeverity: string) {
    setLocation(nextLocation);
    setSeverity(nextSeverity);
    const next = ITEMS.find((item) => (nextLocation === "all" || item.location === nextLocation) && (nextSeverity === "all" || item.severity === nextSeverity));
    if (next && !ITEMS.some((item) => item.id === selectedId && (nextLocation === "all" || item.location === nextLocation) && (nextSeverity === "all" || item.severity === nextSeverity))) setSelectedId(next.id);
  }

  function openReplenishment() {
    if (!selected) return;
    setQuantity(String(selected.suggested));
    setError("");
    setModalOpen(true);
  }

  function confirmMockOrder() {
    if (!selected) return;
    const parsed = Number(quantity);
    if (!Number.isInteger(parsed) || parsed < selected.minimumOrder) {
      setError(`Enter a whole number of at least ${selected.minimumOrder} units.`);
      return;
    }
    setMockOrders((orders) => ({ ...orders, [selected.id]: parsed }));
    setModalOpen(false);
  }

  return (
    <main className="stock-page">
      <PageHeader title="Stock Exceptions" subtitle="Review products below their reorder point and simulate a replenishment before taking action in the inventory system." actions={<Button intent="secondary" leading={<Refresh aria-hidden="true" className="size-[var(--size-icon-md)]" />} onClick={() => { setLocation("all"); setSeverity("all"); setSelectedId(ITEMS[0].id); }}>Reset view</Button>} />

      <section className="filter-bar" aria-label="Exception filters">
        <FieldFrame label="Location"><Select aria-label="Location" value={location} options={[{ value: "all", label: "All locations" }, { value: "Downtown", label: "Downtown" }, { value: "Airport", label: "Airport" }, { value: "Northside", label: "Northside" }]} onValueChange={(value) => changeFilters(value, severity)} /></FieldFrame>
        <FieldFrame label="Severity"><Select aria-label="Severity" value={severity} options={[{ value: "all", label: "All severities" }, { value: "Critical", label: "Critical" }, { value: "Low", label: "Low" }]} onValueChange={(value) => changeFilters(location, value)} /></FieldFrame>
        <p className="filter-summary" role="status">{filtered.length} {filtered.length === 1 ? "exception" : "exceptions"}</p>
      </section>

      <div className="review-layout">
        <section className="exception-list" aria-labelledby="exception-list-title">
          <div className="list-heading"><h2 id="exception-list-title">Products to review</h2><span>On hand / reorder point</span></div>
          {filtered.length ? filtered.map((item) => (
            <Button key={item.id} intent="ghost" className={`exception-row ${selected?.id === item.id ? "is-selected" : ""}`} aria-pressed={selected?.id === item.id} onClick={() => setSelectedId(item.id)}>
              <span className="row-main"><strong>{item.product}</strong><small>SKU {item.sku} · {item.location}</small></span>
              <span className="row-evidence"><StatusPill label={item.severity} tone={item.severity === "Critical" ? "danger" : "warning"} size="xs" /><strong>{item.onHand} / {item.reorderPoint}</strong></span>
            </Button>
          )) : <div className="empty-state"><strong>No matching exceptions</strong><span>Change a location or severity filter to continue reviewing.</span></div>}
        </section>

        <section className="detail-slot" aria-label="Selected stock exception">
          {selected ? <RecordDetailPanel
            title={selected.product}
            subtitle={`SKU ${selected.sku} · ${selected.location}`}
            status={{ label: selected.severity, tone: selected.severity === "Critical" ? "danger" : "warning", detail: `${selected.onHand} on hand` }}
            metadata={[{ id: "demand", label: "Avg. daily sales", value: String(selected.dailySales) }, { id: "coverage", label: "Estimated cover", value: `${Math.max(0.4, selected.onHand / selected.dailySales).toFixed(1)} days` }]}
            sections={[
              { id: "stock", title: "Stock position", collapsible: false, items: [
                { type: "field", id: "on-hand", label: "On hand", value: selected.onHand },
                { type: "field", id: "reorder-point", label: "Reorder point", value: selected.reorderPoint },
                { type: "field", id: "suggested", label: "Suggested replenishment", value: `${selected.suggested} units` },
                { type: "field", id: "open-po", label: "Open purchase order", value: selected.openPo },
                ...(mockOrders[selected.id] ? [{ type: "note" as const, id: "mock-result", title: "Mock replenishment prepared", body: `${mockOrders[selected.id]} units from ${selected.supplier}. This simulation did not create a purchase order.`, tone: "info" as const }] : [])
              ]},
              { id: "supplier", title: "Supplier details", defaultOpen: true, items: [
                { type: "field", id: "supplier", label: "Preferred supplier", value: selected.supplier },
                { type: "field", id: "lead-time", label: "Lead time", value: selected.leadTime },
                { type: "field", id: "minimum", label: "Minimum order", value: `${selected.minimumOrder} units` },
                { type: "field", id: "cost", label: "Unit cost", value: selected.unitCost }
              ]}
            ]}
            actions={[{ id: "replenish", label: mockOrders[selected.id] ? "Revise mock replenishment" : "Try mock replenishment", intent: "primary" }]}
            onAction={openReplenishment}
          /> : <div className="empty-state"><strong>Select a product</strong><span>Choose an exception to review its stock and supplier facts.</span></div>}
        </section>
      </div>

      <Modal open={modalOpen} title="Mock replenishment" description={selected ? `${selected.product} · ${selected.location}` : undefined} onClose={() => { setModalOpen(false); setError(""); }} actions={<div className="modal-actions"><Button intent="secondary" onClick={() => { setModalOpen(false); setError(""); }}>Cancel</Button><Button intent="primary" onClick={confirmMockOrder}>Prepare simulation</Button></div>}>
        {selected ? <div className="modal-body"><p>This only previews a replenishment. No purchase order will be created or sent.</p><FieldFrame label="Quantity" required error={error || undefined} helper={`Suggested ${selected.suggested}; supplier minimum ${selected.minimumOrder}.`}><TextField type="number" min={selected.minimumOrder} step="1" value={quantity} aria-invalid={Boolean(error)} onValueChange={(value) => { setQuantity(value); setError(""); }} /></FieldFrame><div className="order-summary"><span>Supplier</span><strong>{selected.supplier}</strong><span>Lead time</span><strong>{selected.leadTime}</strong></div></div> : null}
      </Modal>
    </main>
  );
}
